/**
 * Replay data loading utilities for the dashboard.
 *
 * Replay files are generated by the Python EventBusReplayWriter and
 * contain the full event stream from a benchmark or workload run,
 * persisted to disk for historical playback.
 */

// ── Types ─────────────────────────────────────────────────────────

/** A single persisted event from the replay file. */
export interface ReplayEvent {
  _event_type: string;
  [key: string]: unknown;
}

/** Full replay session data (mirrors Python _ReplaySession.to_replay_data). */
export interface ReplayData {
  version: string;
  generated_at: string;
  run_id: string;
  model: string;
  workload: string;
  provider: string;
  started_at: string;
  event_count: number;
  events: ReplayEvent[];
}

/** Lightweight entry in the replay index manifest. */
export interface ReplayIndexEntry {
  run_id: string;
  model: string;
  workload: string;
  provider: string;
  started_at: string;
  event_count: number;
  file: string;
}

export interface ReplayManifest {
  version: string;
  generated_at: string;
  total_replays: number;
  replays: ReplayIndexEntry[];
}

// ── Helpers ──────────────────────────────────────────────────────

function emptyManifest(): ReplayManifest {
  return {
    version: "1.0.0",
    generated_at: new Date().toISOString(),
    total_replays: 0,
    replays: [],
  };
}

// ── Loaders ──────────────────────────────────────────────────────

/** Directory where replay files are stored (relative to project root). */
const REPLAYS_DIR = "results/replays";

/**
 * Load the replay manifest (index of all recorded replay sessions).
 * SSR: reads from results/replays/index.json.
 * Browser: fetches /api/replays.
 */
export async function loadReplayManifest(): Promise<ReplayManifest> {
  if (import.meta.env.SSR) {
    try {
      const fs = await import("fs");
      const path = await import("path");
      const filePath = path.resolve(process.cwd(), REPLAYS_DIR, "index.json");
      const raw = fs.readFileSync(filePath, "utf-8");
      return JSON.parse(raw) as ReplayManifest;
    } catch {
      return emptyManifest();
    }
  }

  try {
    const resp = await fetch("/api/replays");
    if (!resp.ok) return emptyManifest();
    const data = await resp.json();
    return {
      version: "1.0.0",
      generated_at: "",
      total_replays: data.length,
      replays: data,
    };
  } catch {
    return emptyManifest();
  }
}

/**
 * Load a single replay session by run_id.
 * SSR: reads from results/replays/{run_id}.json with sanitised filename.
 * Browser: fetches /api/replays/{run_id}.
 */
export async function loadReplay(runId: string): Promise<ReplayData | null> {
  if (import.meta.env.SSR) {
    try {
      const fs = await import("fs");
      const path = await import("path");
      // Sanitise the run_id same way Python does
      const safeName = runId.replace(/[^a-zA-Z0-9\-_.]/g, "_") || "replay";
      const filePath = path.resolve(
        process.cwd(),
        REPLAYS_DIR,
        `${safeName}.json`,
      );
      const raw = fs.readFileSync(filePath, "utf-8");
      return JSON.parse(raw) as ReplayData;
    } catch {
      return null;
    }
  }

  try {
    const resp = await fetch(
      `/api/replays/${encodeURIComponent(runId)}`,
    );
    if (!resp.ok) return null;
    return (await resp.json()) as ReplayData;
  } catch {
    return null;
  }
}

/**
 * Load a filtered list of replay index entries.
 */
export async function loadReplayList(options?: {
  model?: string;
  limit?: number;
  offset?: number;
}): Promise<ReplayIndexEntry[]> {
  if (import.meta.env.SSR) {
    const manifest = await loadReplayManifest();
    let filtered = [...manifest.replays];

    if (options?.model) {
      const model = options.model.toLowerCase();
      filtered = filtered.filter((r) =>
        r.model.toLowerCase().includes(model),
      );
    }

    filtered.sort(
      (a, b) =>
        new Date(b.started_at).getTime() - new Date(a.started_at).getTime(),
    );

    const offset = options?.offset ?? 0;
    const limit = options?.limit ?? filtered.length;
    return filtered.slice(offset, offset + limit);
  }

  const params = new URLSearchParams();
  if (options?.model) params.set("model", options.model);
  if (options?.limit) params.set("limit", String(options.limit));
  if (options?.offset) params.set("offset", String(options.offset));

  const query = params.toString();
  const url = `/api/replays${query ? `?${query}` : ""}`;
  try {
    const resp = await fetch(url);
    if (!resp.ok) return [];
    return (await resp.json()) as ReplayIndexEntry[];
  } catch {
    return [];
  }
}
